+func TestFortinetOnlyCpeDetectionAndEnrichment(t *testing.T) {
+	detail := cvemodels.CveDetail{CveID: "CVE-2023-0001", Fortinets: []cvemodels.Fortinet{{
+		AdvisoryID: "FG-IR-23-001", AdvisoryURL: "https://www.fortiguard.com/psirt/FG-IR-23-001",
+		Title: "FortiOS issue", Summary: "Affected FortiOS versions",
+		DetectionMethod: cvemodels.FortinetExactVersionMatch,
+	}}}
+	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		switch r.URL.Path {
+		case "/cpes":
+			_ = json.NewEncoder(w).Encode([]cvemodels.CveDetail{detail})
+		case "/cves/CVE-2023-0001":
+			_ = json.NewEncoder(w).Encode(detail)
+		default:
+			t.Errorf("unexpected path: %s", r.URL.Path)
+			http.NotFound(w, r)
+		}
+	}))
