+	if !ok {
+		t.Fatalf("Fortinet-only CVE was not detected: %#v", result.ScannedCves)
+	}
+	if len(v.DistroAdvisories) != 1 || v.DistroAdvisories[0].AdvisoryID != "FG-IR-23-001" {
+		t.Errorf("advisories: %#v", v.DistroAdvisories)
+	}
+	if err := FillCvesWithNvdJvnFortinet(&result, cnf, logging.LogOpts{}); err != nil {
+		t.Fatal(err)
+	}
+	contents := result.ScannedCves[detail.CveID].CveContents[models.Fortinet]
+	if len(contents) != 1 || contents[0].SourceLink != "https://www.fortiguard.com/psirt/FG-IR-23-001" || contents[0].Summary != "Affected FortiOS versions" {
+		t.Errorf("Fortinet content: %#v", contents)
+	}
+}
