+func TestFortinetConfidenceUsesStrongestSource(t *testing.T) {
+	tests := []struct {
+		name   string
+		detail cvemodels.CveDetail
+		want   models.Confidence
+	}{
+		{"fortinet exact", cvemodels.CveDetail{Fortinets: []cvemodels.Fortinet{{DetectionMethod: cvemodels.FortinetExactVersionMatch}}}, models.FortinetExactVersionMatch},
+		{"fortinet rough beats NVD vendor", cvemodels.CveDetail{Fortinets: []cvemodels.Fortinet{{DetectionMethod: cvemodels.FortinetRoughVersionMatch}}, Nvds: []cvemodels.Nvd{{DetectionMethod: cvemodels.NvdVendorProductMatch}}}, models.FortinetRoughVersionMatch},
+		{"NVD exact beats fortinet vendor", cvemodels.CveDetail{Fortinets: []cvemodels.Fortinet{{DetectionMethod: cvemodels.FortinetVendorProductMatch}}, Nvds: []cvemodels.Nvd{{DetectionMethod: cvemodels.NvdExactVersionMatch}}}, models.NvdExactVersionMatch},
+		{"JVN alone", cvemodels.CveDetail{Jvns: []cvemodels.Jvn{{}}}, models.JvnVendorProductMatch},
+		{"empty", cvemodels.CveDetail{}, models.Confidence{}},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			if got := getMaxConfidence(tt.detail); got != tt.want {
+				t.Errorf("got %v, want %v", got, tt.want)
+			}
+		})
+	}
+}
+
+func TestDetectCveByCpeURIKeepsFortinetWithoutJVN(t *testing.T) {
