+		if r.URL.Path != "/cpes" {
+			t.Errorf("path: %s", r.URL.Path)
+		}
+		_ = json.NewEncoder(w).Encode([]cvemodels.CveDetail{
+			{CveID: "fortinet", Fortinets: []cvemodels.Fortinet{{AdvisoryID: "FG-1"}}, Jvns: []cvemodels.Jvn{{}}},
+			{CveID: "nvd", Nvds: []cvemodels.Nvd{{}}},
+			{CveID: "jvn", Jvns: []cvemodels.Jvn{{}}},
+		})
+	}))
+	defer srv.Close()
+	got, err := (goCveDictClient{baseURL: srv.URL}).detectCveByCpeURI("cpe:/o:fortinet:fortios:4.3.0", false)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(got) != 2 || got[0].CveID != "fortinet" || len(got[0].Jvns) != 0 || got[1].CveID != "nvd" {
+		t.Fatalf("unexpected matches: %#v", got)
+	}
+}
