diff --git a/models/fortinet_test.go b/models/fortinet_test.go
new file mode 100644
index 0000000..fc292dc
--- /dev/null
+++ b/models/fortinet_test.go
@@ -0,0 +1,64 @@
+package models
+
+import (
+	"reflect"
+	"testing"
+	"time"
+
+	cvedict "github.com/vulsio/go-cve-dictionary/models"
+)
+
+func TestConvertFortinetToModelPreservesAdvisory(t *testing.T) {
+	published := time.Date(2023, 1, 2, 0, 0, 0, 0, time.UTC)
+	modified := published.Add(24 * time.Hour)
+	got := ConvertFortinetToModel("CVE-2023-0001", []cvedict.Fortinet{{
+		AdvisoryID: "FG-IR-23-001", Title: "FortiOS issue", Summary: "Affected versions",
+		AdvisoryURL:   "https://www.fortiguard.com/psirt/FG-IR-23-001",
+		Cvss3:         cvedict.FortinetCvss3{Cvss3: cvedict.Cvss3{BaseScore: 8.1, VectorString: "CVSS:3.1/AV:N", BaseSeverity: "HIGH"}},
+		Cwes:          []cvedict.FortinetCwe{{CweID: "CWE-79"}},
+		References:    []cvedict.FortinetReference{{Reference: cvedict.Reference{Link: "https://example.com/fix", Source: "Fortinet"}}},
+		PublishedDate: published, LastModifiedDate: modified,
+	}})
+	want := []CveContent{{Type: Fortinet, CveID: "CVE-2023-0001", Title: "FortiOS issue", Summary: "Affected versions",
+		Cvss3Score: 8.1, Cvss3Vector: "CVSS:3.1/AV:N", Cvss3Severity: "HIGH",
+		SourceLink: "https://www.fortiguard.com/psirt/FG-IR-23-001", CweIDs: []string{"CWE-79"},
+		References: []Reference{{Link: "https://example.com/fix", Source: "Fortinet"}},
+		Published:  published, LastModified: modified}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("got %#v, want %#v", got, want)
+	}
+}
+
+func TestFortinetContentAppearsBeforeNvd(t *testing.T) {
+	v := VulnInfo{CveContents: CveContents{
+		Nvd:      {{Type: Nvd, Summary: "NVD summary", Cvss3Score: 7}},
+		Fortinet: {{Type: Fortinet, Title: "Fortinet title", Summary: "Fortinet summary", Cvss3Score: 8}},
+	}}
+	if got := v.Titles("en", ""); !reflect.DeepEqual(got, []CveContentStr{{Fortinet, "Fortinet summary"}, {Nvd, "NVD summary"}}) {
+		t.Errorf("titles: %v", got)
+	}
+	if got := v.Summaries("en", ""); !reflect.DeepEqual(got, []CveContentStr{{Fortinet, "Fortinet summary"}, {Nvd, "NVD summary"}}) {
+		t.Errorf("summaries: %v", got)
+	}
+	if got := v.Cvss3Scores(); len(got) != 2 || got[0].Type != Fortinet || got[1].Type != Nvd {
+		t.Errorf("scores: %v", got)
+	}
+}
+
+func TestFortinetAdvisoryURLAppearsInPrimarySources(t *testing.T) {
+	contents := CveContents{Fortinet: {{Type: Fortinet, SourceLink: "https://www.fortiguard.com/psirt/FG-IR-23-001"}}}
+	want := []CveContentStr{{Fortinet, "https://www.fortiguard.com/psirt/FG-IR-23-001"}}
+	if got := contents.PrimarySrcURLs("en", "", "CVE-2023-0001", nil); !reflect.DeepEqual(got, want) {
+		t.Errorf("primary sources: got %v, want %v", got, want)
+	}
+}
+
+func TestNewCveContentsKeepsDistinctFortinetAdvisories(t *testing.T) {
+	contents := NewCveContents(
+		CveContent{Type: Fortinet, SourceLink: "https://example.com/FG-1"},
+		CveContent{Type: Fortinet, SourceLink: "https://example.com/FG-2"},
+	)
+	if got := contents[Fortinet]; len(got) != 2 || got[0].SourceLink != "https://example.com/FG-1" || got[1].SourceLink != "https://example.com/FG-2" {
+		t.Errorf("Fortinet advisories: %#v", got)
+	}
+}
